          entries(10001);
        }
        if (failure.equals("capacity"))
          h.publishAction =
              () -> {
                throw new CapacityExceededException();
              };
        if (failure.equals("io"))
          h.publishAction =
              () -> {
                throw new IOException("synthetic file provider text");
