        temporary(() -> h.service.process(request));
        assertEquals(replaced, stored(request));
        assertEquals(0, h.live.get());
        sql(FIXTURE_DELETE_FROM_SCHUBERT_SCRIPT_ENTRIES_76A083AC);
        entries(201);
      }
      sql(FIXTURE_DELETE_FROM_SCHUBERT_SCRIPT_ENTRIES_76A083AC);
      sql("delete from schubert.script_files");
