  private static void assertCleanupFunctionGuards() throws SQLException {
    for (Map.Entry<String, Integer> cleanup : CLEANUP_FUNCTION_LIMITS.entrySet()) {
      String function = "schubert." + cleanup.getKey();
      assertEquals(
          "BACKUP_GATE",
          queryString(
              FIXTURE_SCHUBERT_BATCH_F9C88479,
              "select reason_code from " + function + "('" + UUID_1 + "','" + FIXED_TIME + "',1)"));
      assertSqlState(
          FIXTURE_SCHUBERT_BATCH_F9C88479,
          FIXTURE_22023_CDCA15BB,
          FIXTURE_SELECT_FROM_06A9ABF0 + function + "(null,'" + FIXED_TIME + "',1)");
      assertSqlState(
          FIXTURE_SCHUBERT_BATCH_F9C88479,
          FIXTURE_22023_CDCA15BB,
          FIXTURE_SELECT_FROM_06A9ABF0 + function + "('" + UUID_1 + "',null,1)");
      assertSqlState(
          FIXTURE_SCHUBERT_BATCH_F9C88479,
          FIXTURE_22023_CDCA15BB,
          FIXTURE_SELECT_FROM_06A9ABF0 + function + "('" + UUID_1 + "','" + FIXED_TIME + "',0)");
      assertSqlState(
          FIXTURE_SCHUBERT_BATCH_F9C88479,
          FIXTURE_22023_CDCA15BB,
          FIXTURE_SELECT_FROM_06A9ABF0
              + function
              + "('"
              + UUID_1
              + "','"
              + FIXED_TIME
              + "',"
              + (cleanup.getValue() + 1)
              + ")");
    }
    try (Connection holder = connection(ADMIN)) {
      holder.setAutoCommit(false);
      execute(holder, "select pg_advisory_xact_lock(71419602)");
      for (String cleanup : CLEANUP_FUNCTION_LIMITS.keySet()) {
        assertEquals(
            "LOCK_BUSY",
            queryString(
                FIXTURE_SCHUBERT_BATCH_F9C88479,
                "select reason_code from schubert."
                    + cleanup
                    + "('"
                    + UUID_1
                    + "','"
                    + FIXED_TIME
                    + "',1)"));
      }
      holder.rollback();
    }
  }

