  private static String call(Connection c, String name, String cutoff, int limit)
      throws SQLException {
    return scalar(
        c,
        "select target_count||'|'||deleted_count||'|'||skipped_count||'|'||reason_code from "
            + function(name)
            + "('"
            + RUN
            + "',"
