      c.commit();
      assertEquals("6", scalar(FIXTURE_SELECT_COUNT_FROM_BDA3EEC8 + TABLE));
      assertEquals("0|0|0|OK", purge(c, RUN, CUTOFF.toString(), 1000));
      c.commit();
      for (Integer limit : Arrays.asList(null, 0, 1001))
