            "select count(*) from schubert.auth_sessions where user_id=7 and revoked_at='2026-09-08T01:00:00Z' and revoke_reason='LOGOUT' and last_accessed_at='2026-09-08T00:00:00Z' and expires_at='2026-09-08T08:00:00Z'"));
