  private static Optional<Throwable> mdb3254Fault(String kind) {
    return switch (kind) {
      case FIXTURE_NONE_C44E6DD7 -> Optional.empty();
      case FIXTURE_SQL_5B7E398D -> Optional.of(new SQLException("PT3254_SQL_DRIVER", "XX000"));
