                                        FIXTURE_TARGET_COUNT_5B6567D4,
                                        FIXTURE_SUCCESS_COUNT_716E5185,
                                        FIXTURE_FAILURE_COUNT_C7E67F21,
                                        FIXTURE_BYTE_COUNT_6D76E237)
                                    .contains(field)) return 0L;
                                return observedValue;
                              });
                        });
