            assertEquals(
                attempt == 1 ? started.plusSeconds(3) : observed,
                r.getTimestamp(FIXTURE_ENDED_AT_E151E393).toInstant());
            assertEquals(
                attempt == 1 ? FIXTURE_SUCCESS_10855C7F : "SKIPPED",
